mapper.select:
SELECT 
FROM distribution_commission c
JOIN distribution_partner p ON p.partner_id = c.partner_id AND p.del_flag = '0'
JOIN mobile_user pu ON pu.user_id = p.user_id AND pu.del_flag = '0'
JOIN mobile_user ou ON ou.user_id = c.referred_user_id AND ou.del_flag = '0'
WHERE 1 = 1
AND c.partner_id = #{partnerId}

    AND (p.partner_no LIKE CONCAT('%', #{partnerKeyword}, '%')
        OR pu.nick_name LIKE CONCAT('%', #{partnerKeyword}, '%'))

AND ou.phone LIKE CONCAT('%', #{phone}, '%')
AND c.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND c.product_type = #{productType}
AND c.status = #{status}
AND c.pay_time >= #{payStart}
AND c.pay_time <= #{payEnd}
ORDER BY c.pay_time DESC, c.commission_id DESC

SELECT 
FROM distribution_withdrawal w
JOIN distribution_partner p ON p.partner_id = w.partner_id AND p.del_flag = '0'
JOIN mobile_user u ON u.user_id = p.user_id AND u.del_flag = '0'
WHERE 1 = 1
AND w.partner_id = #{partnerId}
AND w.withdrawal_no LIKE CONCAT('%', #{withdrawalNo}, '%')

    AND (p.partner_no LIKE CONCAT('%', #{partnerKeyword}, '%')
        OR u.nick_name LIKE CONCAT('%', #{partnerKeyword}, '%'))

AND u.phone LIKE CONCAT('%', #{phone}, '%')
AND w.method_type = #{methodType}
AND w.status = #{status}
AND w.apply_time >= #{applyStart}
AND w.apply_time <= #{applyEnd}
ORDER BY w.apply_time DESC, w.withdrawal_id DESC
